from helpers import D, src, DSM, mk
from functools import partial
CARDS = []
X = partial(mk, "further-study", "further-study", "flask-conical")
DSM_X = DSM("Section III: Conditions for Further Study")
CHR = src("src-chr-transition", "Transition to psychosis in clinical high-risk individuals: meta-analysis of 130 studies", "JAMA Psychiatry (Salazar de Pablo et al.)", "https://jamanetwork.com/journals/jamapsychiatry/fullarticle/2781884", 2021, seen=True)
SHORT_HYPO = src("src-short-hypomania", "Depression with shorter hypomanic episodes (review)", "Current Psychiatry Reports", "https://link.springer.com/article/10.1007/s11920-016-0669-2", 2016, seen=True, note="Not opened.")
CUD = src("src-caffeine-cud", "Prevalence and correlates of caffeine use disorder symptoms among a United States sample", "PubMed Central (PMC7071067)", "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC7071067/", 2020, seen=True)
CAF_WD = src("src-caffeine-withdrawal", "A critical review of caffeine withdrawal: empirical validation of symptoms and signs", "Johns Hopkins (Juliano & Griffiths)", "https://pure.johnshopkins.edu/en/publications/a-critical-review-of-caffeine-withdrawal-empirical-validation-of--5/", 2004, seen=True)
IGD = src("src-igd-prev", "Global prevalence of gaming disorder: a systematic review and meta-analysis", "Australian & New Zealand Journal of Psychiatry (Stevens et al.), DOI 10.1177/0004867420962851", "https://doi.org/10.1177/0004867420962851", 2021, note="DOI from earlier search; not opened.")
FASD = src("src-fasd-united", "FASD United Family Navigator", "FASD United (formerly NOFAS)", "https://fasdunited.org/family-navigator", seen=True, note="Phone numbers conflict across listings.")
SWANNELL = src("src-swannell-nssi", "Prevalence of nonsuicidal self-injury in nonclinical samples: systematic review, meta-analysis and meta-regression", "Suicide and Life-Threatening Behavior (Swannell et al.), 44(3):273–303", "https://researchers.westernsydney.edu.au/en/publications/prevalence-of-nonsuicidal-self-injury-in-nonclinical-samples-syst/", 2014, seen=True)
WHO_SUIC = src("src-who-suicide", "Suicide fact sheet", "World Health Organization", "https://www.who.int/news-room/fact-sheets/detail/suicide", 2025, note="Figures from search summaries; page not opened.")
X_NOTE = ["Marked 'proposed, not official' on the card face: these are research criteria, not diagnoses."]
SAFE_MSG = ["Safe-messaging rules apply: no methods, no numbers that sensationalise."]

CARDS.append(X("attenuated-psychosis-syndrome", "Attenuated Psychosis Syndrome", "Early, mild psychosis-like experiences, watched with care", ["clinical high risk for psychosis (CHR-P)", "at-risk mental state", "psychosis prodrome"], "n/a (proposed)",
 "Mild, recent experiences a bit like psychosis, while you still know they may not be real. Proposed for early help.",
 "Attenuated psychosis syndrome is a proposed diagnosis, not an official one. It describes people, usually young, with mild experiences a bit like psychosis. They may have unusual beliefs, feel suspicious, hear faint things, or speak in a jumbled way. These began or got worse in the past year, and the person knows they may not be real. The label exists to get people early support. Most never develop a psychotic disorder, and early help improves things for everyone.",
 ["I kept feeling people were talking about me and I knew that was probably my mind. The early intervention team didn't label me; they just helped.", "Two years on, the experiences faded. I'm glad someone took them seriously without panicking."],
 ["Mild unusual beliefs, suspiciousness, or faint hallucination-like experiences", "Started or got worse in the past year, happening at least weekly", "Insight kept: the person knows the experiences may not be real", "Distress or worry prompting someone to seek help"],
 [{"myth": "This means you're going to develop schizophrenia.", "fact": "About 1 in 5 people meeting high-risk criteria develop a psychotic disorder within two years; most don't. Many improve completely."},
  {"myth": "You should be put on antipsychotics straight away.", "fact": "Guidelines favour monitoring, CBT, and support first. Antipsychotics are not recommended for prevention."}],
 {"plain": "Among people found to be at high risk, about 1 in 5 develop a psychotic disorder within two years, and about 1 in 4 within three.", "figure": "Cumulative transition risk 19% at 2 years, 25% at 3 years across 130 studies (9,222 people)", "source_ref": "src-chr-transition"},
 {"plain_summary": "Early help services offer a full check, regular follow-up, CBT for these experiences, and family support. They treat depression, anxiety, or drug use, and help you stay in school or work. Antipsychotic medicines aren't advised to prevent psychosis. If a disorder does develop, treatment starts at once. That's the point of staying connected.",
  "evidence_based_options": ["Early intervention or at-risk mental state services with regular monitoring", "CBT for psychosis-like experiences", "Family support and psychoeducation", "Treatment of co-occurring depression, anxiety, or substance use"],
  "self_help_that_supports_care": ["Sleep, and reducing cannabis and stimulants", "Telling someone what you're experiencing", "Staying connected to school, work, and friends", "Learning that unusual experiences are common and often pass"],
  "guideline_refs": ["src-chr-transition"]},
 "If unusual experiences are worrying you, especially if they've grown over recent months, ask a doctor about an early help service. If the experiences start to feel real or frightening, or you have thoughts of harming yourself, use the crisis strip now.",
 "A vivid imagination, spiritual experiences, odd moments when exhausted, and experiences only while on drugs aren't this. A full psychotic episode is diagnosed and treated as one.",
 "Most people with these experiences get better. Being watched over early is a safety net, not a sentence.",
 ["schizophrenia", "brief-psychotic-disorder", "schizotypal-personality-disorder", "major-depressive-disorder", "cannabis-use-disorder"],
 ["prodrome", "early-intervention-service", "first-episode-psychosis", "insight", "psychosis"],
 ["hearing-voices-network-groups", "sczaction-peer-groups", "nami-connection-and-helpline"],
 ("Soft line illustration of a young person and a youth worker walking along a river path, talking, a bridge ahead in soft morning light. Pastel violet and mint.", "A young person and a youth worker walk along a river path toward a bridge."),
 [DSM_X, CHR], sens="elevated", notes=X_NOTE, card_type="further-study", clin=True))

CARDS.append(X("depressive-episodes-with-short-duration-hypomania", "Depressive Episodes with Short-Duration Hypomania", "Depression with brief highs under the four-day rule", ["short-duration hypomania", "subthreshold bipolar", "bipolar spectrum"], "n/a (proposed)",
 "Major depression plus short highs of two or three days, not long enough to count as bipolar II.",
 "This proposed category is for people who've had major depression and also short highs of two or three days. In a high, they have unusual energy, need less sleep, have racing ideas, or act on impulse. The highs don't last the four days bipolar II needs. Research suggests they are more like people with bipolar II than with depression alone. That matters, because antidepressants alone can sometimes set off a high. It's listed so clinicians watch for it.",
 ["Two days of feeling like I could do anything, then back into the hole. Nobody asked about the highs because they were so short.", "Once my psychiatrist knew about the short highs, we changed the plan, and the crashes got shallower."],
 ["Major depressive episodes, past or present", "At least one two-to-three-day period of elevated mood, energy, and less sleep", "Not long enough to count as a hypomanic episode", "Often a family history of bipolar disorder"],
 [{"myth": "If it doesn't last four days, it doesn't count.", "fact": "The four-day rule is a convention. Short highs carry much of the same information and may change treatment choices."}],
 {"plain": "Among people with depression, a fair number report short highs. The figures vary a lot with how the question is asked.", "figure": "In one multicentre study of 5,635 people in a depressive episode, 25% of reported hypomanic episodes were shorter than four days", "source_ref": "src-short-hypomania", "note": "Open the review to confirm figures."},
 {"plain_summary": "Treatment is for the depression, but with care. Clinicians may lean toward what works for bipolar depression: talk therapy plus a mood-steadying medicine, prescribed and monitored by a doctor. If antidepressants are used, they watch closely. Tracking your mood, keeping regular sleep, and learning to spot highs are central.",
  "evidence_based_options": ["Careful assessment of mood history, including brief highs", "Psychotherapy (CBT, interpersonal and social rhythm therapy)", "Medication decisions that account for bipolar risk, prescribed and monitored by a doctor", "Mood and sleep tracking"],
  "self_help_that_supports_care": ["Telling your clinician about short highs, not just lows", "Regular sleep times", "Involving someone who notices your mood shifts", "Mood-tracking apps or diaries"],
  "guideline_refs": []},
 "If you have depression and also brief periods of unusually high energy or little need for sleep, tell your clinician; it can change treatment. If depression becomes severe or you have thoughts of ending your life, use the crisis strip.",
 "Normal good days, relief after depression lifts, or energy from stimulants or lack of sleep aren't hypomania. Four or more days of hypomania is bipolar II.",
 "Getting the pattern right often ends years of treatment that didn't quite work.",
 ["bipolar-ii-disorder", "major-depressive-disorder", "cyclothymic-disorder", "bipolar-i-disorder"],
 ["hypomania", "mixed-features", "mood-stabilizer", "episode", "euthymia"],
 ["dbsa-online-support-groups", "bipolar-uk-ecommunity", "reddit-r-bipolar"],
 ("Soft line illustration of a person filling in a simple mood chart on a kitchen wall calendar with coloured dots, a sleeping cat nearby, morning light. Pastel violet and peach.", "A person marks a mood chart on a kitchen calendar with coloured dots."),
 [DSM_X, SHORT_HYPO], sens="elevated", notes=X_NOTE, card_type="further-study", clin=True))

CARDS.append(X("caffeine-use-disorder", "Caffeine Use Disorder", "When coffee and energy drinks are a problem you can't shake", ["caffeine dependence", "caffeine withdrawal (official diagnosis)"], "n/a (proposed)",
 "A proposed diagnosis for people who can't cut down caffeine despite harm, with withdrawal when they stop.",
 "Caffeine is the world's most used drug, and most people use it without trouble. Caffeine use disorder is a proposed category for people who keep using it despite physical or mental harm, such as insomnia, anxiety, heart palpitations, or stomach problems, have tried and failed to cut down, and get withdrawal, like headache and fatigue, when they stop. Caffeine withdrawal is already an official diagnosis. The bar for the proposed disorder is deliberately high so ordinary coffee drinking isn't labelled.",
 ["Six energy drinks a day, panic attacks, and I couldn't sleep. Cutting down over a month was rough but the anxiety halved.", "I didn't think coffee counted as a drug until I tried to stop and spent three days in bed with a headache."],
 ["Persistent wish or failed attempts to cut down caffeine", "Continued use despite insomnia, anxiety, palpitations, or stomach problems caused by it", "Withdrawal when stopping: headache, fatigue, irritability, low mood", "Using to avoid withdrawal"],
 [{"myth": "Caffeine can't be a real problem.", "fact": "Withdrawal is well documented, and high intake worsens anxiety, insomnia, and panic in some people. For a minority, cutting down is genuinely hard."},
  {"myth": "Everyone who drinks coffee daily has a disorder.", "fact": "The proposed criteria require harm plus failed attempts to cut down plus withdrawal. Daily coffee alone isn't close."}],
 {"plain": "In one US survey of caffeine users, about 8 in 100 met the proposed criteria. About half of people who stop abruptly get a withdrawal headache.", "figure": "About 8% of 1,006 US caffeine consumers met proposed criteria (2020 survey); withdrawal headache in about 50% in experimental studies, with clinically significant impairment in 13%", "source_ref": "src-caffeine-cud"},
 {"plain_summary": "Gradual reduction over weeks avoids most withdrawal: swapping in lower-caffeine drinks, moving the last dose earlier, and cutting one serving at a time. Brief counselling helps people stick with it. Treating underlying anxiety, insomnia, or ADHD, which often drive heavy use, matters. Withdrawal symptoms peak in the first two days and pass within about a week.",
  "evidence_based_options": ["Gradual taper of caffeine over weeks", "Brief counselling or CBT-based reduction programmes", "Treatment of underlying anxiety, insomnia, or ADHD", "Sleep hygiene and routine"],
  "self_help_that_supports_care": ["Counting your real daily intake, including energy drinks and pre-workouts", "Cutting by one serving every few days rather than stopping cold", "No caffeine after early afternoon", "Expecting a few days of headache and tiredness, then relief"],
  "guideline_refs": ["src-caffeine-withdrawal"]},
 "If caffeine is causing anxiety, panic, insomnia, or heart symptoms and you can't cut down, talk to a doctor or pharmacist. Seek urgent care for chest pain or a racing heartbeat that won't settle.",
 "Enjoying coffee, needing it to wake up, or a headache when you miss it aren't a disorder. Anxiety and panic from other causes are diagnosed separately.",
 "Most people who cut down find sleep and calm return within weeks, and discover they like coffee more when it isn't a need.",
 ["generalized-anxiety-disorder", "panic-disorder", "insomnia-disorder", "stimulant-use-disorder", "adhd"],
 ["withdrawal", "tolerance", "dependence", "sleep-hygiene", "tapering"],
 ["smart-recovery-meetings", "reddit-r-insomnia", "reddit-r-anxiety"],
 ("Soft line illustration of a person at a café table with a herbal tea and a cup of coffee, choosing the tea, a notebook with a tapering plan, sunlight. Pastel violet and cream.", "A person at a café table chooses a herbal tea over coffee, a notebook open beside them."),
 [DSM_X, CUD, CAF_WD], notes=X_NOTE, card_type="further-study"))

CARDS.append(X("internet-gaming-disorder", "Internet Gaming Disorder", "When gaming takes over and you can't pull back", ["gaming disorder (ICD-11, official)", "video game addiction", "problem gaming"], "n/a (proposed in DSM; 6C51 in ICD-11)",
 "Persistent gaming that takes over life and continues despite harm, proposed in DSM and official in ICD-11.",
 "Internet gaming disorder is a proposed DSM category, and an official ICD-11 diagnosis, for people whose gaming has taken over: loss of control, gaming taking priority over school, work, sleep, and relationships, and continuing despite clear harm, for a year or more. Most gamers, including heavy ones, don't have it. It often sits alongside depression, anxiety, ADHD, or social difficulties, with gaming as an escape. Treatment helps people regain control, which doesn't always mean quitting.",
 ["I wasn't playing because it was fun any more. I was playing because everything else felt impossible. Treating the depression changed the gaming.", "My son's gaming was the symptom. The problem was he'd been bullied out of every real-world friendship he had."],
 ["Loss of control over when and how long you game", "Gaming takes priority over sleep, school, work, hygiene, or relationships", "Continuing despite real harm: grades, job, health, relationships", "Irritability or low mood when unable to play", "Pattern lasting about a year, with significant impairment"],
 [{"myth": "Anyone who games a lot is addicted.", "fact": "Hours alone don't define it. Loss of control plus harm plus persistence do. Many people game heavily and function well."},
  {"myth": "Taking the console away fixes it.", "fact": "Abrupt removal often escalates conflict and misses what gaming was doing for the person. Treating the underlying difficulties and rebuilding offline life works better."}],
 {"plain": "Around 3 in 100 people worldwide meet criteria for gaming disorder, by a large review, and fewer with stricter definitions. It's more common in boys and young men.", "figure": "Pooled prevalence 3.05% (1.96% with stringent sampling) across 53 studies in 17 countries", "source_ref": "src-igd-prev"},
 {"plain_summary": "CBT adapted for gaming has the best evidence: understanding what gaming provides, building control strategies, and rebuilding offline activities and relationships. Family therapy helps with younger people. Treating depression, anxiety, ADHD, or social anxiety often reduces gaming on its own, with any medication prescribed and monitored by a doctor. Peer communities of people who've cut back or quit help with motivation. Specialist clinics exist in some countries.",
  "evidence_based_options": ["CBT for internet gaming disorder", "Family therapy for adolescents", "Treatment of co-occurring depression, anxiety, ADHD, or social anxiety", "Peer support communities focused on regaining control"],
  "self_help_that_supports_care": ["Tracking real hours and what you were avoiding", "Rebuilding one offline thing: sport, music, a person", "Removing games from the bedroom; protecting sleep", "Peer groups of people who've reduced or quit"],
  "guideline_refs": ["src-igd-prev"]},
 "If gaming is costing you sleep, school, work, or relationships and you can't cut back despite wanting to, talk to a doctor or therapist, and look for a peer community. For a young person, start with a calm conversation about what gaming is giving them.",
 "Enjoying games, heavy gaming during holidays, or gaming as a hobby and social life aren't a disorder. Gambling features inside games are covered under gambling disorder.",
 "People regain control, often while still enjoying games. Many describe rediscovering a life they'd been avoiding.",
 ["gambling-disorder", "major-depressive-disorder", "social-anxiety-disorder", "adhd", "autism-spectrum-disorder"],
 ["impulsivity", "avoidance", "cbt", "relapse-prevention", "doomscrolling"],
 ["reddit-r-stopgaming", "smart-recovery-meetings", "youngminds-parents-helpline"],
 ("Soft line illustration of two friends playing basketball at a park court at golden hour, a games console visible through an open window behind, a dog watching. Pastel violet and amber.", "Two friends play basketball at a park court at golden hour."),
 [DSM_X, IGD], qs=["Open the meta-analysis to confirm figures."], notes=X_NOTE, card_type="further-study", young="Gaming disorder peaks in adolescence. Parents do best by staying curious about what the game provides, setting limits together, and getting help for anxiety, bullying, or ADHD underneath."))

CARDS.append(X("neurobehavioral-disorder-prenatal-alcohol-exposure", "Neurobehavioral Disorder Associated with Prenatal Alcohol Exposure", "Thinking and behaviour differences from alcohol before birth", ["ND-PAE", "fetal alcohol spectrum disorder (FASD)", "FAS, ARND"], "n/a (proposed; coded as other specified neurodevelopmental disorder)",
 "Lasting trouble with thinking, self-control, and daily life caused by alcohol before birth.",
 "This is the DSM's proposed name for the brain effects of alcohol before birth. It's part of what's usually called fetal alcohol spectrum disorder (FASD). It brings trouble with thinking (memory, learning, planning), self-control (mood, attention, impulses), and daily life (social skills, independence). It starts in childhood and lasts. Most children with it don't have the facial features of FAS. It's often mistaken for ADHD or 'bad behaviour'. The right support makes a big difference.",
 ["He was labelled naughty for ten years. The FASD diagnosis rewrote the story: his brain works differently, and now school works with that.", "I'm an adult with FASD. I need lists, routine, and people who don't assume I'm being difficult."],
 ["Trouble with memory, learning, planning, or seeing what will happen next", "Trouble regulating mood, attention, and impulses", "Trouble with social skills, daily living, or managing alone", "Starting in childhood, with confirmed or likely alcohol exposure before birth", "Often misdiagnosed as ADHD, ODD, or a learning disorder alone"],
 [{"myth": "You can see FASD in a child's face.", "fact": "Only a minority have the facial features. Most people with the condition look like anyone else, which is why it's missed."},
  {"myth": "It's the mother's fault and nothing can be done.", "fact": "Blame helps no one; many pregnancies are unplanned, and alcohol advice has changed over time. Early diagnosis and tailored support improve outcomes greatly."}],
 {"plain": "Estimates suggest FASD affects between 1 and 5 in 100 children in the US, depending on the study. That makes it one of the most common causes of developmental difficulty, and one of the most often missed.", "figure": "National estimates of 2%–5% of individuals (US summaries); figures vary by study and region", "source_ref": "src-dsm", "note": "Needs the primary May 2018 JAMA prevalence study citation."},
 {"plain_summary": "There's no cure, but the right support changes lives. That means a diagnosis from a specialist team, school plans built around memory and thinking differences, set routines, clear and simple instructions, skills training for daily life and social situations, and support for parents and carers. ADHD, anxiety, or sleep problems alongside it are treated, with any medication prescribed and monitored by a doctor. Adult services, housing, and job support matter for independence.",
  "evidence_based_options": ["Multidisciplinary FASD assessment", "Individualised school plans and environmental supports", "Parent and carer training and support", "Treatment of co-occurring ADHD, anxiety, or sleep problems"],
  "self_help_that_supports_care": ["External structure: visual schedules, lists, routines", "Concrete, one-step instructions", "Family navigator services and FASD support organisations", "Protecting from blame; the brain, not the person, is the issue"],
  "guideline_refs": []},
 "If a child or adult has learning, attention, and behaviour problems that don't fit ADHD alone, and alcohol in pregnancy is known or possible, ask about an FASD assessment. Family navigator services can help you find one.",
 "ADHD, autism, learning disorders, and trauma can look similar and can co-occur. A single learning difficulty without the broader pattern isn't ND-PAE.",
 "With the right scaffolding, people with FASD finish school, hold jobs, and live well. Understanding changes everything.",
 ["adhd", "intellectual-developmental-disorder", "specific-learning-disorder", "oppositional-defiant-disorder", "autism-spectrum-disorder"],
 ["neurodevelopmental", "executive-function", "school-support-plans", "reasonable-accommodations", "late-diagnosis"],
 ["fasd-united-family-navigator", "chadd-online-communities", "youngminds-parents-helpline"],
 ("Soft line illustration of a child using a picture schedule on a fridge with a parent, a star chart, morning light. Pastel violet and sunflower.", "A child and a parent use a picture schedule on a fridge."),
 [DSM_X, FASD], qs=["Add the primary prevalence citation (JAMA 2018)."], notes=X_NOTE + ["Non-blaming language toward birth parents throughout."], card_type="further-study", lang="mixed", lang_note="'Person with FASD' is common; some self-advocates use 'FASD adult'. Both are used here."))

CARDS.append(X("suicidal-behavior-disorder", "Suicidal Behavior Disorder", "Recording a suicide attempt so care stays focused on safety", ["suicide attempt (proposed diagnosis)"], "n/a (proposed)",
 "A proposed category for people who've made a suicide attempt within the past two years, to keep safety central.",
 "Suicidal behavior disorder is a proposed, not official, category for someone who has made a suicide attempt in the past two years. It isn't a disorder of character; it records that an attempt happened so that care keeps safety and follow-up at the centre, whatever other diagnosis a person has. A past attempt is the strongest single predictor of future risk, and most people who survive an attempt do not die by suicide. Follow-up matters most in the months afterwards.",
 ["After my attempt I was discharged with a leaflet. Six months later a different hospital gave me a safety plan, a follow-up call every week, and a therapist. That's the version that worked.", "Nobody tells you the first year after is the hardest and the most important. Weekly calls got me through it."],
 ["A suicide attempt within the last two years", "Recorded regardless of any other diagnosis", "Not applied to self-injury without intent to die", "Signals the need for safety planning and follow-up"],
 [{"myth": "Once someone has attempted, they'll always be at risk.", "fact": "Risk is highest in the months after and falls with time and support. Most attempt survivors go on to live, and many describe deep relief that they did."}],
 {"plain": "Attempts are far more common than deaths; estimates suggest many attempts for every death. Most people who attempt survive and recover.", "figure": "WHO estimates attempts outnumber deaths many times over; over 720,000 suicide deaths worldwide each year (2025 fact sheet)", "source_ref": "src-who-suicide", "note": "Present carefully; avoid numbers that sensationalise."},
 {"plain_summary": "What helps after an attempt: a safety plan made with a clinician, rapid follow-up (a call or visit within days, not weeks), therapy that targets suicidal thinking (CBT for suicide prevention, DBT, CAMS), treatment of any underlying condition with any medication prescribed and monitored by a doctor, involving trusted people, and making the environment safer. Brief contact interventions, like follow-up messages, reduce repeat attempts. Peer support with other attempt survivors helps with shame and isolation.",
  "evidence_based_options": ["Safety planning and rapid follow-up after discharge", "CBT for suicide prevention, DBT, or CAMS", "Treatment of underlying depression, trauma, substance use, or other conditions", "Brief contact follow-up and peer support for attempt survivors"],
  "self_help_that_supports_care": ["Keeping your safety plan where you can find it", "Telling one person you trust what helps when things get dark", "Attending follow-up even when you feel better", "Peer groups where attempt survivors talk openly"],
  "guideline_refs": ["src-who-suicide"]},
 "If you've attempted and are struggling again, reach out now: a crisis line from the strip, a trusted person, or an emergency department. If you're supporting someone after an attempt, ask directly how they are, help them keep follow-up appointments, and keep the lines of contact open.",
 "Nonsuicidal self-injury, done to cope rather than to die, is recorded separately. Suicidal thoughts without an attempt are covered on the suicidal thoughts card.",
 "Most attempt survivors are alive years later, and many become the people who help others through. The period after an attempt is when support changes everything.",
 ["suicidal-thoughts-and-behavior", "nonsuicidal-self-injury-disorder", "major-depressive-disorder", "borderline-personality-disorder", "posttraumatic-stress-disorder"],
 ["suicide-attempt-survivor", "safety-plan", "crisis-plan", "safe-messaging", "warning-signs"],
 ["alt2su-wildflower-alliance", "nami-connection-and-helpline", "mind-side-by-side", "sane-forums-australia"],
 ("Soft line illustration of a person answering a phone call on a sunny porch, a mug of tea, a dog at their feet, a calendar with a circled date. Pastel violet and gold.", "A person answers a phone call on a sunny porch with a dog at their feet."),
 [DSM_X, WHO_SUIC], sens="high", notes=X_NOTE + SAFE_MSG, card_type="further-study", clin=True))

CARDS.append(X("nonsuicidal-self-injury-disorder", "Nonsuicidal Self-Injury Disorder", "A proposed diagnosis for frequent, hard-to-stop self-injury", ["NSSI disorder"], "n/a (proposed)",
 "A proposed category for self-injury on five or more days in a year, done to cope, causing distress.",
 "Nonsuicidal self-injury disorder is a proposed, not official, diagnosis for people who've injured themselves on five or more days in a year, without wanting to die, to relieve bad feelings, with distress because of it. It's listed so that self-injury can be recognised in its own right, not only as a symptom of borderline personality disorder, which it often isn't. The care is the same as for self-injury generally: understanding what it does, and building other ways to cope.",
 ["Having a name for it that wasn't 'borderline' mattered. I'm not; I was a teenager who'd found one way to cope and needed others.", "The urge still shows up on bad days. Now it's a signal to use my list, not a secret."],
 ["Self-injury on five or more days in the past year, without intent to die", "Done to relieve bad feelings, resolve a problem, or feel something", "Urges or preoccupation beforehand", "Distress or problems in daily life because of it"],
 [{"myth": "Frequent self-injury means borderline personality disorder.", "fact": "Many people who self-injure don't have BPD. The proposed disorder exists partly to stop that automatic assumption."}],
 {"plain": "Around 1 in 6 teenagers has self-injured at some point; a smaller number do so often enough to meet the proposed criteria.", "figure": "Lifetime NSSI 17.2% in adolescents, 5.5% in adults (meta-analysis, 2014); proposed-disorder prevalence not established", "source_ref": "src-swannell-nssi"},
 {"plain_summary": "DBT and DBT skills groups have the strongest evidence, especially for teens; CBT, family-based therapy, and treatment of underlying depression, anxiety, or trauma help too, with any medication prescribed and monitored by a doctor. Wound care without judgement and honest conversation about urges are central. Recovery means the urges losing their power, not perfection.",
  "evidence_based_options": ["DBT or DBT skills groups, including adolescent versions", "CBT and family-based therapy", "Treatment of underlying depression, anxiety, or trauma", "Non-judgemental medical care"],
  "self_help_that_supports_care": ["A written list of things that delay or replace the urge", "Telling one trusted person", "Tracking urges and triggers", "Recovery-focused online resources, not pro-self-harm spaces"],
  "guideline_refs": ["src-swannell-nssi"]},
 "If you're self-injuring regularly and want it to change, a therapist, doctor, or school counsellor can help, and crisis and text lines in the strip are there for the hard moments. Seek urgent medical care for serious injuries. If you're thinking about ending your life, reach out now.",
 "Occasional self-injury, body modification, and self-injury with intent to die are not this proposed disorder.",
 "People stop. Urges fade with new ways to cope, and the self-injury becomes something they used to do.",
 ["nonsuicidal-self-injury", "suicidal-behavior-disorder", "borderline-personality-disorder", "major-depressive-disorder"],
 ["self-harm", "emotional-dysregulation", "dbt", "coping-skills", "safe-messaging"],
 ["cornell-self-injury-recovery-resources", "alt2su-wildflower-alliance", "mind-side-by-side"],
 ("Soft line illustration of a teenager drawing in a sketchbook at a kitchen table while a parent cooks nearby, afternoon light. Pastel violet and mint. No injuries shown.", "A teenager draws in a sketchbook at a kitchen table while a parent cooks nearby."),
 [DSM_X, SWANNELL], sens="high", notes=X_NOTE + SAFE_MSG + ["No descriptions of methods, tools, or wounds."], card_type="further-study", clin=True))
